/**
 * Starter templates for the KMIP Developer tab (dev-tabs-pkcs11-kmip plan
 * WS-E). Same role as ../pipeline/pipelineTemplates.ts on the PKCS#11 side.
 *
 * "Governed lifecycle" reproduces the shape of the sandbox's own real
 * samples/py/17-kmip-cacp.py sample (proven live in P3) — CreateKeyPair,
 * a governed refusal BEFORE Activate, Activate, Sign, GetAttributes,
 * Locate, Revoke, Destroy — the exact teaching moment the whole KMIP
 * Developer tab exists for.
 *
 * The ACVP templates (2026-08-30, Python-grammar-realignment plan follow-up)
 * are genuine NIST Known-Answer Tests, not simulated ones: real fixed key
 * material and real expected output, copied verbatim from
 * pqctoday-hsm/tests/acvp/{mlkem_test,mldsa_test}.json — themselves traced
 * to real NIST ACVP-Server sample vectors (see each template's own
 * PROVENANCE comment for the exact source_url/source_sha256/tcId). Register
 * (KMIP 3.0 Operation 0x00000003, §6.1.50) imports the vector's own fixed
 * key — every other template generates a fresh random one instead, which
 * is honest for teaching the lifecycle but cannot reproduce a KAT's exact
 * expected output.
 */
import type { KmipStep } from './kmipPipelineCodegen'

// ── ACVP ML-KEM-768 real vector (FIPS 203) ──────────────────────────────────
// PROVENANCE: pqctoday-hsm/tests/acvp/mlkem_test.json, tgId=2 (ML-KEM-768)
// tcId=26, source_url=https://raw.githubusercontent.com/usnistgov/ACVP-Server/
// 975de31eb83d87039ec88934fdc47d8c312b892d/gen-val/json-files/
// ML-KEM-encapDecap-FIPS203/internalProjection.json,
// source_sha256=a556952ce869bb89c3a3196a701dad89647c193a34c86eafb61a9d710d5b810f
// retrieved 2026-08-23. Byte lengths cross-checked against FIPS 203's own
// ML-KEM-768 sizes (sk=2400B, pk=1184B, ct=1088B, ss=32B) — all match.
const ACVP_MLKEM768_SK =
  ''
const ACVP_MLKEM768_CT =
  ''
const ACVP_MLKEM768_SS = '79D74F6C6C2D916BEC47BD828FD9B67295A37F54927FAB1263C0D122F1C6F1ED'

